return {api_version=1,id="EX1_334",name="Shadow Madness",text="Gain control of an enemy minion with 3 or less Attack until end of turn.",set="EXPERT1",type="spell",class="priest",rarity="rare",spell_school="shadow",cost=3,target_mode="required",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:enemy_minions(self))do if ctx:entity(e).attack<=3 then r[#r+1]=e end end;return r end,on_play=function(ctx,self,target)ctx:change_controller_until_end_of_turn(target,ctx:controller(self))end}
